export declare const NOTES_STYLESHEET = "\n.rx-notes-panel {\n  position: absolute;\n  inset: 0;\n  display: flex;\n  flex-direction: column;\n  background: var(--rx-ground);\n}\n.rx-notes-searchbar {\n  display: flex;\n  gap: var(--rx-space-2);\n  padding: var(--rx-space-2) var(--rx-space-3);\n  border-bottom: 1px solid var(--rx-border);\n  flex: 0 0 auto;\n}\n.rx-notes-search-input {\n  flex: 1 1 auto;\n  min-height: 48px;\n  padding: 0 var(--rx-space-2);\n  border: 1px solid var(--rx-border);\n  border-radius: var(--rx-radius);\n  background: var(--rx-surface);\n  color: var(--rx-ink);\n  font-size: 14px;\n}\n.rx-notes-sort {\n  min-height: 48px;\n  min-width: 44px;\n  border: 1px solid var(--rx-border);\n  border-radius: var(--rx-radius);\n  background: var(--rx-surface);\n  color: var(--rx-ink);\n  font-size: 13px;\n}\n.rx-notes-filters {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--rx-space-2);\n  padding: var(--rx-space-2) var(--rx-space-3);\n  border-bottom: 1px solid var(--rx-border);\n  flex: 0 0 auto;\n}\n.rx-notes-chip {\n  min-height: 44px;\n  padding: 0 var(--rx-space-3);\n  border: 1px solid var(--rx-border);\n  border-radius: var(--rx-radius);\n  background: var(--rx-surface);\n  color: var(--rx-muted);\n  font-size: 13px;\n  cursor: pointer;\n}\n.rx-notes-chip.active {\n  color: var(--rx-ink);\n  border-color: var(--rx-accent);\n  background: var(--rx-surface-2);\n}\n.rx-notes-banner {\n  padding: var(--rx-space-2) var(--rx-space-3);\n  font-size: 12px;\n  color: var(--rx-muted);\n  background: var(--rx-surface-2);\n  flex: 0 0 auto;\n}\n.rx-notes-list {\n  position: relative;\n  flex: 1 1 auto;\n  min-height: 0;\n  overflow-y: auto;\n}\n.rx-notes-row {\n  display: flex;\n  align-items: center;\n  gap: var(--rx-space-2);\n  min-height: 48px;\n  padding: var(--rx-space-2) var(--rx-space-3);\n  border-bottom: 1px solid var(--rx-border);\n  background: none;\n  border-left: none;\n  border-right: none;\n  border-top: none;\n  text-align: left;\n  color: var(--rx-ink);\n  font-size: 13px;\n  width: 100%;\n  cursor: pointer;\n}\n.rx-notes-row:hover {\n  background: var(--rx-surface-2);\n}\n.rx-notes-row-swatch {\n  flex: 0 0 14px;\n  width: 14px;\n  height: 14px;\n  border-radius: 50%;\n  background: var(--rx-notes-row-color, var(--rx-muted));\n}\n.reader-shell.e-ink .rx-notes-row-swatch {\n  border-radius: 0;\n  border: 1px solid var(--rx-ink);\n}\n.rx-notes-row-body {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n  flex: 1 1 auto;\n}\n.rx-notes-row-snippet {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.rx-notes-row-meta {\n  font-size: 11px;\n  color: var(--rx-muted);\n}\n.rx-notes-loading-row {\n  min-height: 48px;\n  display: flex;\n  align-items: center;\n  padding: 0 var(--rx-space-3);\n  color: var(--rx-muted);\n  font-size: 12px;\n}\n.rx-notes-empty {\n  padding: var(--rx-space-4);\n  color: var(--rx-muted);\n  font-size: 13px;\n  text-align: center;\n}\n";
